def rb(w):
    if w < 90:
        return w, 'NE'
    elif w < 180:
        return 180 - w, 'SE'
    elif w < 270:
        return w - 180, 'SW'
    else:
        return 360 - w, 'NW'

for w in (145, 250):
    r, q = rb(w)
    print(f'{r:.1f}')
    print(f'{(w + 180) % 360:.1f}')

